// LTTC research page: a chart of every research step, and a detail card for the selected step.
// Data: milestones.json (written by hand) and rescored.json (generated by
// GP50_reverse_engineer/scripts/tone_capture/export_research_page_20261126.py).

import {setLiveSources} from './live.mjs';
import {diagram} from './diagram.mjs';

// Audio clips are served from the R2 bucket lttc-data through the data Worker
// (GP50_reverse_engineer/tools/tone_trainer/data_worker). Files there never change: re-exported clips get a new version.
const AUDIO = 'https://lttc-data.sfranjou.workers.dev/research/v1/audio';

const [{teachers, short, sources, blocks, milestones}, rescored, live, levels] = await Promise.all(
  ['milestones.json', 'rescored.json', 'live/index.json', 'levels.json'].map(file => fetch(file).then(r => r.json())));

const TEACHER_IDS = Object.keys(teachers);
const color = id => `var(--amp-${id})`;
const BY = {owner: 'Suggested by Sebastian', ai: 'Found by the AI agent', unclear: 'Unclear who proposed it'};
const METRIC = {mfcc: 'PaperMFCC', esr: 'ESR'};

const form = document.getElementById('controls');
const svg = document.getElementById('chart');
const tooltip = document.getElementById('tooltip');
const card = document.getElementById('card');
let selected = {milestone: milestones.at(-1).id, model: null};

// Amps switched off by clicking their name in the chart's legend.
// Start with a few amps that span the whole story; the others are one click away in the legend.
const SHOWN_AT_START = ['a2_reference', 'peavey', 'marshall', 'vexter'];
const hiddenTeachers = new Set(TEACHER_IDS.filter(t => !SHOWN_AT_START.includes(t)));

const settings = () => ({
  mode: form.mode.value,
  metric: form.metric.value,
  teachers: TEACHER_IDS.filter(t => !hiddenTeachers.has(t)),
});

// Every point the chart can draw for one step, in the current mode.
function points(m, s) {
  if (s.mode === 'historical') {
    return m.reported.filter(r => r.metric === s.metric && s.teachers.includes(r.teacher))
      .map(r => ({teacher: r.teacher, value: r.value, label: r.label, lead: !!r.lead}));
  }
  return m.models.flatMap(model => s.teachers
    .filter(t => rescored.scores[t]?.[model.id])
    // "lead": true for every amp, or a list of the amps where this model was the one kept.
    .map(t => ({teacher: t, value: rescored.scores[t][model.id][s.metric], label: model.label,
                lead: model.lead === true || !!model.lead?.includes?.(t), model: model.id})));
}

// ---------- chart ----------

const W = 1000, H = 420, LEFT = 90, RIGHT = 150, TOP = 16, BOTTOM = 110;
const SVG = 'http://www.w3.org/2000/svg';

function add(parent, tag, attributes, text) {
  const node = document.createElementNS(SVG, tag);
  for (const [k, v] of Object.entries(attributes)) node.setAttribute(k, v);
  if (text !== undefined) node.textContent = text;
  parent.append(node);
  return node;
}

// Who proposed a step: small person / robot / question-mark icons, drawn once in <defs> and reused.
const ICONS = `
  <symbol id="icon-owner" viewBox="0 0 24 24"><circle cx="12" cy="7.5" r="4.5"/><path d="M3 22a9 8 0 0 1 18 0z"/></symbol>
  <symbol id="icon-ai" viewBox="0 0 24 24"><path d="M12 1.5v4" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="2" r="1.8"/>
    <rect x="3.5" y="5.5" width="17" height="14" rx="3.5"/><circle cx="9" cy="11.5" r="2" fill="var(--paper)"/>
    <circle cx="15" cy="11.5" r="2" fill="var(--paper)"/><path d="M8.5 16h7" stroke="var(--paper)" stroke-width="1.6"/>
    <path d="M1.5 10v5M22.5 10v5" stroke="currentColor" stroke-width="2"/></symbol>
  <symbol id="icon-unclear" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9.5" fill="none" stroke="currentColor" stroke-width="2"/>
    <text x="12" y="17" text-anchor="middle" font-size="14" font-weight="700" fill="currentColor">?</text></symbol>`;

function icon(parent, by, x, y, size = 18) {
  return add(parent, 'use', {href: `#icon-${by}`, x: x - size / 2, y: y - size / 2, width: size, height: size,
    fill: 'currentColor', color: 'var(--ink)', 'pointer-events': 'none'});
}

// Right-hand legend, one entry per amp; a short dashed stroke after the dot means it has a SnapTone line too.
// Entries are kept in y order and pushed apart so they never overlap. Clicking one shows or hides that amp; hidden amps stay listed, greyed out.
function labels(parent, items, x, gap = 14) {
  items.sort((a, b) => a.y - b.y);
  for (let i = 1; i < items.length; i++) items[i].y = Math.max(items[i].y, items[i - 1].y + gap);
  for (const item of items) {
    const off = hiddenTeachers.has(item.teacher);
    const paint = off ? 'var(--line)' : color(item.teacher);
    const g = add(parent, 'g', {class: 'legend-item' + (off ? ' off' : ''), role: 'button', tabindex: 0,
      'aria-pressed': String(!off)});
    add(g, 'title', {}, (off ? 'Show ' : 'Hide ') + teachers[item.teacher]);
    add(g, 'rect', {x, y: item.y - 7, width: RIGHT - 14, height: 14, fill: 'transparent'});  // easier to click
    add(g, 'circle', {cx: x + 5, cy: item.y, r: 4, fill: paint});
    if (item.snaptone) add(g, 'line', {x1: x + 11, x2: x + 22, y1: item.y, y2: item.y, stroke: paint, 'stroke-width': 1, 'stroke-dasharray': '3 2'});
    add(g, 'text', {x: x + 27, y: item.y + 4}, item.text);
    const toggle = () => {
      off ? hiddenTeachers.delete(item.teacher) : hiddenTeachers.add(item.teacher);
      draw();
      svg.querySelector(`.legend-item[data-teacher="${item.teacher}"]`)?.focus();
    };
    g.dataset.teacher = item.teacher;
    g.addEventListener('click', toggle);
    g.addEventListener('keydown', event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); toggle(); } });
  }
}

function draw() {
  const s = settings();
  svg.innerHTML = `<defs>${ICONS}</defs>`;
  const step = (W - LEFT - RIGHT) / (milestones.length - 1);
  const x = i => LEFT + i * step;
  const all = milestones.map(m => points(m, s));
  // SnapTone lines for every amp that has one; only the shown amps are drawn.
  const snaptoneAll = s.mode === 'rescored'
    ? TEACHER_IDS.filter(t => rescored.scores[t]?.snaptone).map(t => ({teacher: t, value: rescored.scores[t].snaptone[s.metric]}))
    : [];
  // The axis range covers every amp in this view, shown or not, so hiding an amp moves nothing else.
  const every = milestones.map(m => points(m, {...s, teachers: TEACHER_IDS}));
  const values = [...every.flat(), ...snaptoneAll].map(p => p.value).filter(v => v > 0);
  const bottom = TOP + (H - TOP - BOTTOM);
  let low = Math.min(...values) / 1.3, high = Math.max(...values) * 1.3;
  if (!values.length) low = 1, high = 10;
  // Log scale: the scores span almost two orders of magnitude.
  const y = v => bottom - (Math.log(v / low) / Math.log(high / low)) * (bottom - TOP);

  for (let e = Math.floor(Math.log10(low)); e <= Math.ceil(Math.log10(high)); e++) {
    for (const k of [1, 2, 5]) {
      const v = k * 10 ** e;
      if (v < low || v > high) continue;
      add(svg, 'line', {x1: LEFT, x2: W - RIGHT, y1: y(v), y2: y(v), class: 'grid'});
      add(svg, 'text', {x: LEFT - 6, y: y(v) + 4, 'text-anchor': 'end'}, String(+v.toPrecision(2)));
    }
  }
  add(svg, 'text', {x: 4, y: TOP + 4, 'dominant-baseline': 'hanging'}, METRIC[s.metric]);

  // One clickable column per step, so steps without a score can still be selected.
  milestones.forEach((m, i) => {
    const column = add(svg, 'rect', {x: x(i) - step / 2, y: TOP, width: step, height: H - TOP - 20,
      fill: 'transparent', class: 'column' + (m.id === selected.milestone ? ' selected' : '')});
    column.addEventListener('mousemove', event => show(event, m));
    column.addEventListener('mouseleave', hide);
    column.addEventListener('click', () => select(m.id, null));
    const newDate = i === 0 || m.date !== milestones[i - 1].date;
    if (newDate) {
      const date = new Date(m.date + 'T12:00').toLocaleDateString('en', {month: 'short', day: 'numeric'});
      add(svg, 'text', {x: x(i), y: bottom + 14, transform: `rotate(-40 ${x(i)} ${bottom + 14})`, 'text-anchor': 'end'}, date);
    }
    icon(svg, m.direction.by, x(i), H - 30);
  });
  add(svg, 'text', {x: 4, y: H - 26}, 'Idea from');

  // The legend lists every amp with data in this view, at the height of its last point (kept inside the plot).
  const legend = [];
  const inside = v => Math.min(Math.max(y(v), TOP), bottom);
  for (const p of snaptoneAll) {
    if (s.teachers.includes(p.teacher)) add(svg, 'line', {x1: LEFT, x2: W - RIGHT, y1: y(p.value), y2: y(p.value),
      stroke: color(p.teacher), 'stroke-width': 1, 'stroke-dasharray': '5 4', opacity: .8});
  }

  // A line through the lead model of each step, one per shown amp. Each amp gets one legend entry, at the
  // height of its last point (or of its SnapTone line if it has no point in this view).
  for (const t of TEACHER_IDS) {
    const own = every.flatMap((ps, i) => ps.filter(p => p.teacher === t).map(p => ({...p, i})));
    const snap = snaptoneAll.find(p => p.teacher === t);
    if (!own.length && !snap) continue;
    const lead = own.filter(p => p.lead);
    const last = lead.at(-1) ?? own.at(-1) ?? snap;
    legend.push({y: inside(last.value), teacher: t, text: short[t], snaptone: !!snap});
    if (s.teachers.includes(t) && lead.length > 1)
      add(svg, 'polyline', {points: lead.map(p => [x(p.i), y(p.value)]).join(' '), fill: 'none', stroke: color(t), 'stroke-width': 2});
  }
  labels(svg, legend, W - RIGHT + 14);

  all.forEach((ps, i) => ps.forEach(p => {
    // Side experiments are hollow and nudged sideways so they do not hide the lead point.
    const cx = x(i) + (p.lead ? 0 : step * .25);
    const dot = add(svg, 'circle', {cx, cy: y(p.value), r: p.lead ? 5 : 4, stroke: color(p.teacher), 'stroke-width': 2,
      fill: p.lead ? color(p.teacher) : 'var(--paper)'});
    if (p.model === selected.model && milestones[i].id === selected.milestone) dot.setAttribute('stroke', 'var(--ink)');
    dot.addEventListener('mousemove', event => show(event, milestones[i], p));
    dot.addEventListener('mouseleave', hide);
    dot.addEventListener('click', () => select(milestones[i].id, p.model ?? null));
  }));

  document.getElementById('key-snaptone').hidden = s.mode !== 'rescored';  // SnapTone is only in the re-scored view
  document.getElementById('mode-note').textContent = s.mode === 'rescored'
    ? 'Every saved model is scored again on the same held-out audio, after the fact. NAM is the target, so it scores 0.'
    : 'Scores as recorded in each study. Each study used its own validation audio, so scores are only roughly comparable, and ESR was replaced by PaperMFCC from Oct 21.';
}

function show(event, m, p) {
  const previous = milestones[milestones.indexOf(m) - 1];
  tooltip.innerHTML = `<p><strong>${m.title}</strong> · ${m.date}</p>` +
    (p ? `<p><span class="swatch" style="background:${color(p.teacher)}"></span>${p.label}: ${p.value.toPrecision(3)}</p>` : '') +
    `<p>${archText(m.architecture)}</p>` +
    `<p>${previous ? 'Changed: ' : ''}${m.changed}</p>`;
  tooltip.hidden = false;
  const box = svg.parentElement.getBoundingClientRect();
  const left = event.clientX - box.left + 14;
  tooltip.style.left = Math.min(left, box.width - tooltip.offsetWidth) + 'px';
  tooltip.style.top = event.clientY - box.top + 14 + 'px';
}

function hide() { tooltip.hidden = true; }

// ---------- detail card ----------

// An architecture is a list of block names; {"parallel": [[...], [...]]} is a group of branches fed the same input.
// Blocks show a short label (e.g. "↓4"); the hover gives the full name and explanation.
const label = name => blocks[name]?.label ?? name;

function archText(nodes) {
  return nodes.map(n => typeof n === 'string' ? label(n) : '[' + n.parallel.map(b => b.map(label).join(' → ')).join(' ‖ ') + ']').join(' → ');
}

// "Also tried" lists: alternatives, not a signal path, so plain boxes separated by dots.
function options(nodes) {
  return '<ol class="options">' + nodes.map(n => `<li><span class="block">${label(n)}</span></li>`).join('') + '</ol>';
}

// One tooltip for every architecture block, filled from milestones.json "blocks".
const blockTip = document.getElementById('block-tip');
function showBlock(event) {
  const target = event.target.closest('[data-block]');
  if (!target) return;
  const b = blocks[target.dataset.block];
  // b.math is MathML, drawn natively by the browser.
  blockTip.innerHTML = `<p><strong>${b.term}</strong></p><p>${b.text}</p>` + (b.math ? `<div class="math">${b.math}</div>` : '');
  blockTip.hidden = false;
  const box = target.getBoundingClientRect();
  blockTip.style.left = Math.max(8, Math.min(box.left, innerWidth - blockTip.offsetWidth - 8)) + 'px';
  blockTip.style.top = box.bottom + 6 + 'px';
}
card.addEventListener('mouseover', showBlock);
card.addEventListener('focusin', showBlock);
card.addEventListener('mouseout', event => { if (event.target.closest('[data-block]')) blockTip.hidden = true; });
card.addEventListener('focusout', () => { blockTip.hidden = true; });

// level: the clip's natural loudness relative to its NAM clip (levels.json). Files are all level-matched; with
// "Match loudness" off, each clip's volume is set back to its natural level relative to the loudest in its group.
function audioRow(label, src, level = 1) {
  return `<span>${label}</span><audio controls preload="none" src="${src}" data-level="${level}"></audio>`;
}

let matchLoudness = true;
function applyLoudness() {
  for (const group of card.querySelectorAll('.clips')) {
    const players = [...group.querySelectorAll('audio')];
    const loudest = Math.max(...players.map(a => Number(a.dataset.level)));
    for (const a of players) a.volume = matchLoudness ? 1 : Number(a.dataset.level) / loudest;
  }
}
card.addEventListener('change', event => {
  if (event.target.id !== 'match-loudness') return;
  matchLoudness = event.target.checked;
  applyLoudness();
});

const isLead = (model, t) => model.lead === true || !!model.lead?.includes?.(t);

function renderCard() {
  const s = settings();
  const m = milestones.find(item => item.id === selected.milestone);
  const model = m.models.find(item => item.id === selected.model) ?? m.models.find(item => item.lead) ?? m.models[0];
  const branches = (m.branches ?? []).map(b => `<p class="note">${b.label}</p>${options(b.nodes)}`).join('');

  const rows = m.models.flatMap(item => TEACHER_IDS.filter(t => rescored.scores[t]?.[item.id]).map(t => {
    const score = rescored.scores[t][item.id], base = rescored.scores[t].snaptone;
    return `<tr><td><span class="swatch" style="background:${color(t)}"></span>${teachers[t]}</td><td>${item.label}</td>` +
      `<td class="number">${score.mfcc.toFixed(2)}</td><td class="number">${score.esr.toFixed(3)}</td>` +
      `<td class="number">${base ? base.mfcc.toFixed(2) : '—'}</td></tr>`;
  })).join('');
  const reported = m.reported.map(r => `<tr><td><span class="swatch" style="background:${color(r.teacher)}"></span>${teachers[r.teacher]}</td>` +
    `<td>${r.label}</td><td>${METRIC[r.metric]}</td><td class="number">${r.value.toPrecision(3)}</td></tr>`).join('');

  let clips = '';
  if (s.mode === 'rescored') {
    // Per amp: the clicked model if it has this amp, otherwise this step's kept model for that amp.
    const modelFor = t => [m.models.find(x => x.id === selected.model), ...m.models.filter(x => isLead(x, t)), ...m.models]
      .find(x => x && rescored.scores[t]?.[x.id]);
    const passages = m.passages ?? [{suffix: '', label: ''}];
    clips = TEACHER_IDS.filter(t => modelFor(t)).map(t => {
      const pick = modelFor(t), level = name => levels.rescored[t]?.[name] ?? 1;
      const file = (name, p) => name + (p.suffix ? '_' + p.suffix : '');
      const rows = passages.map(p => (p.label ? `<h5>${p.label}</h5>` : '') + '<div class="clips">' +
        audioRow('Dry guitar', `${AUDIO}/rescored/${t}/${file('dry', p)}.mp3`, level(file('dry', p))) +
        audioRow('NAM (target)', `${AUDIO}/rescored/${t}/${file('nam', p)}.mp3`, level(file('nam', p))) +
        (rescored.scores[t].snaptone ? audioRow('SnapTone', `${AUDIO}/rescored/${t}/${file('snaptone', p)}.mp3`, level(file('snaptone', p))) : '') +
        audioRow(pick.label, `${AUDIO}/rescored/${t}/${file(pick.id, p)}.mp3`, level(file(pick.id, p))) + '</div>').join('');
      return `<details${hiddenTeachers.has(t) ? '' : ' open'}><summary>${teachers[t]}</summary>${rows}</details>`;
    }).join('');
  } else if (s.mode === 'historical' && m.clips) {
    const level = levels.historical[m.id] ?? {teacher: 1, model: 1};
    clips = `<div class="clips">${audioRow('NAM (target)', `${AUDIO}/historical/${m.id}/teacher.mp3`, level.teacher)}` +
      `${audioRow('This step', `${AUDIO}/historical/${m.id}/model.mp3`, level.model)}</div>` +
      `<p class="note">The clip published at the time (listening pack ${m.clips.pack}).</p>`;
  }

  card.innerHTML = `<h2>${m.title}</h2>
    <p class="note">${m.date} · ${BY[m.direction.by]}${m.direction.note ? ' — ' + m.direction.note : ''}</p>
    <p>${m.summary}</p>
    <p><strong>What changed:</strong> ${m.changed}</p>
    <h3>Architecture</h3>
    <div class="diagram-scroll">${diagram(m.architecture, blocks)}</div>${branches}
    <p class="note">Hover or focus a block for what it does.</p>
    <h3>Training</h3>
    <table><tr><th>Optimizer</th><td>${m.training.optimizer}</td></tr><tr><th>Loss</th><td>${m.training.loss}</td></tr>
      <tr><th>Data</th><td>${m.training.data}</td></tr></table>
    ${s.mode === 'rescored' && rows ? `<h3>Scores on the held-out audio</h3>
      <table><tr><th>Amp</th><th>Model</th><th>PaperMFCC</th><th>ESR</th><th>SnapTone MFCC</th></tr>${rows}</table>` : ''}
    ${reported ? `<h3>Recorded at the time</h3><table><tr><th>Amp</th><th>Model</th><th>Score</th><th></th></tr>${reported}</table>` : ''}
    ${clips ? `<h3>Listen</h3><p><label><input type="checkbox" id="match-loudness"${matchLoudness ? ' checked' : ''}> Match loudness</label>
      <span class="note">On: every clip plays at the NAM clip's loudness (same RMS), so you compare tone, not volume.
      Off: each clip plays at the level the model really produces.</span></p>${clips}`
      : '<p class="note">No audio for this step in this view.</p>'}`;
  applyLoudness();
}

// ---------- live input: which amps and sources exist for the selected model ----------

const liveTeacher = document.querySelector('#live [name=teacher]');

function selectedModel() {
  const m = milestones.find(item => item.id === selected.milestone);
  return m.models.find(item => item.id === selected.model) ?? m.models.find(item => item.lead) ?? m.models[0];
}

function updateLive(preferModel) {
  // live/index.json: {teacher: [model ids with a live chain]}. The NAM itself comes from the user's own download.
  const model = selectedModel();
  const previous = liveTeacher.value;
  liveTeacher.replaceChildren(...TEACHER_IDS.filter(t => live[t] || sources[t]).map(t => new Option(teachers[t], t)));
  const withModel = TEACHER_IDS.find(t => live[t]?.includes(model?.id));
  // After picking a new step, switch to an amp that has this model live, unless the current one does.
  const keep = (live[previous] || sources[previous]) && !(preferModel && withModel && !live[previous]?.includes(model?.id));
  liveTeacher.value = keep ? previous : withModel ?? liveTeacher.options[0]?.value;
  const t = liveTeacher.value;
  setLiveSources({
    nam: sources[t] ?? null,
    snaptone: live[t]?.includes('snaptone') ? `live/${t}/snaptone.json` : null,
    model: live[t]?.includes(model?.id) ? `live/${t}/${model.id}.json` : null,
    label: model?.label,
  });
}

liveTeacher.addEventListener('change', () => updateLive(false));

function select(milestone, model) {
  selected = {milestone, model};
  draw();
  renderCard();
  updateLive(true);
}

form.addEventListener('change', () => { draw(); renderCard(); });
draw();
renderCard();
updateLive(true);
